#include "techpulse/sources/rss.hpp"
#include "techpulse/normalize/normalize.hpp"
namespace techpulse::sources { namespace {
std::string tag(const std::string&s,const std::string&n){auto a=s.find("<"+n);if(a==std::string::npos)return{};a=s.find('>',a);if(a==std::string::npos)return{};auto b=s.find("</"+n+">",a);return b==std::string::npos?"":s.substr(a+1,b-a-1);}
std::string link(const std::string&s){auto x=tag(s,"link");if(!x.empty())return x;auto a=s.find("<link");a=s.find("href=\"",a);if(a==std::string::npos)return{};a+=6;auto b=s.find('"',a);return s.substr(a,b-a);}
} FetchResult fetch_rss(const std::string& url,const HttpGet& get){FetchResult r;auto x=get(url);if(x.status!=200){r.errors.push_back("RSS returned HTTP "+std::to_string(x.status));return r;}size_t p=0;while(true){auto a=x.body.find("<item",p), e=x.body.find("<entry",p);if(a==std::string::npos&&e==std::string::npos)break;bool atom=e!=std::string::npos&&(a==std::string::npos||e<a);a=atom?e:a;auto b=x.body.find(atom?"</entry>":"</item>",a);if(b==std::string::npos)break;auto o=x.body.substr(a,b-a);model::RadarItem i;i.source_type="rss";i.title=normalize::clean_title(tag(o,"title"));i.url=normalize::canonical_url(link(o));if(!i.title.empty()&&!i.url.empty()){i.source_id=i.url;i.id="rss:"+i.url;i.summary_raw=tag(o,atom?"summary":"description");i.published_at=tag(o,atom?"updated":"pubDate");i.provenance.push_back({"rss",i.source_id,i.url});r.items.push_back(std::move(i));}p=b+7;}return r;} }
